insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('bocachico-en-viuda', 'Bocachico en viuda', 'sopas', 'Ribera del río Magdalena', 'Pescado de río cocido al vapor sobre yuca, plátano y ñame, bañado en un guiso criollo.', 60, 4, 'Media', array['4 bocachicos limpios y escamados', '1 libra de yuca en trozos', '2 plátanos verdes en trozos', '1 libra de ñame en trozos', '2 tomates picados', '1 cebolla cabezona picada', '1 manojo de cebollín picado', '3 dientes de ajo machacados', '1 ají dulce picado', '1 cucharadita de achiote o color', 'Sal, comino y pimienta al gusto', 'Hojas de bijao o de plátano (opcional)']::text[], array['Adoba los bocachicos con sal, ajo, comino y pimienta. Déjalos reposar 15 minutos.', 'En una olla grande pon la yuca, el ñame y el plátano con agua hasta la mitad y un poco de sal. Cocina 15 minutos.', 'Coloca los pescados encima de las verduras, tapa con hojas de bijao o con la tapa y deja que se cocinen al vapor 15 a 20 minutos.', 'Aparte, sofríe en aceite la cebolla, el cebollín, el tomate, el ají y el achiote hasta formar un guiso espeso.', 'Sirve el pescado sobre las verduras y báñalo con el guiso caliente.']::text[], 'La ''viuda'' es una preparación típica de los pueblos ribereños del Magdalena. Se llama así porque el pescado se cocina ''solo'', sin otras carnes, sobre las verduras del campo. El bocachico es el pescado más tradicional de las ciénagas y el río.', 'Receta de referencia — validar con cocineros de Pijiño del Carmen') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('arroz-con-coco', 'Arroz con coco', 'arroces', 'Caribe colombiano', 'Arroz dulce-salado de color caramelo, compañero obligado del pescado frito.', 50, 6, 'Media', array['2 cocos secos', '2 tazas de arroz', '3 cucharadas de azúcar o panela rallada', '1 cucharadita de sal', '1 puñado de uvas pasas (opcional)', 'Agua tibia']::text[], array['Ralla la pulpa de los cocos y mézclala con 4 tazas de agua tibia. Exprime con un lienzo para sacar la leche de coco.', 'Pon la leche en un caldero a fuego medio y déjala hervir hasta que se evapore el agua y quede solo el aceite con el ''cuncho'' dorado.', 'Agrega el azúcar y revuelve hasta que el cuncho tome color caramelo oscuro, sin dejar que se queme.', 'Añade de nuevo agua (unas 4 tazas), la sal y las pasas. Cuando hierva, agrega el arroz lavado.', 'Cocina destapado hasta que seque el agua, luego tapa y baja el fuego al mínimo por 20 minutos.']::text[], 'El arroz con coco es símbolo de la cocina costeña. El punto del ''cuncho'' — el residuo tostado de la leche de coco — es un saber que se transmite de madres a hijas y da el color y sabor característico.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('pescado-frito-patacon', 'Pescado frito con patacón', 'pescados', 'Caribe colombiano', 'Pescado entero dorado y crocante, servido con patacones y ensalada.', 40, 4, 'Fácil', array['4 pescados enteros (mojarra, bocachico o pargo)', '3 plátanos verdes', '2 limones', '3 dientes de ajo machacados', 'Sal al gusto', 'Aceite para freír', 'Ensalada de tomate y cebolla para acompañar']::text[], array['Haz cortes diagonales a cada lado del pescado. Adóbalo con sal, ajo y jugo de limón por 15 minutos.', 'Calienta bastante aceite en un caldero. Fríe el pescado 6 a 8 minutos por lado hasta que esté dorado y crujiente.', 'Pela los plátanos, córtalos en trozos de 3 cm y fríelos hasta que ablanden.', 'Aplasta cada trozo con una tabla o ''patacona'', pásalo por agua con sal y vuelve a freír hasta dorar.', 'Sirve el pescado con los patacones, ensalada y, si quieres, arroz con coco.']::text[], 'Es el almuerzo de domingo por excelencia en el Caribe. El patacón, plátano verde frito dos veces, acompaña casi todas las comidas de la región.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('mote-de-queso', 'Mote de queso', 'sopas', 'Sabanas del Caribe (Sucre, Córdoba, Bolívar)', 'Sopa espesa de ñame con queso costeño, ajo y suero.', 50, 6, 'Fácil', array['2 libras de ñame pelado y en cubos', '1/2 libra de queso costeño duro en cubos', '1 cebolla cabezona picada', '3 dientes de ajo', '1 manojo de cebollín', '1 limón', 'Suero costeño al gusto', 'Sal al gusto']::text[], array['Cocina el ñame en 8 tazas de agua con sal hasta que esté muy blando, unos 30 minutos.', 'Aparte, sofríe la cebolla, el ajo y el cebollín en un poco de aceite.', 'Agrega el sofrito a la olla y bate con un molinillo o cuchara para que el ñame espese la sopa.', 'Añade el queso en cubos y unas gotas de limón. Cocina 5 minutos más, sin que el queso se derrita del todo.', 'Sirve caliente con suero, arroz blanco o bollo limpio.']::text[], 'El mote de queso es uno de los platos más queridos de la región sabanera. El ñame es un cultivo tradicional del Caribe, y Colombia está entre los mayores productores del mundo.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('arroz-de-lisa', 'Arroz de lisa', 'arroces', 'Barranquilla y Bajo Magdalena', 'Arroz amarillo con lisa salada desmechada y verduras.', 60, 6, 'Media', array['1 libra de lisa salada', '2 tazas de arroz', '1 zanahoria rallada', '1 cebolla cabezona picada', '1 manojo de cebollín', '1 pimentón picado', '2 tomates picados', '3 dientes de ajo', '1 cucharadita de achiote', 'Sal y comino al gusto']::text[], array['Remoja la lisa salada desde la noche anterior, cambiando el agua varias veces.', 'Cocina la lisa 15 minutos, retira la piel y las espinas y desmenúzala. Guarda el caldo.', 'Sofríe la cebolla, el cebollín, el pimentón, el tomate, el ajo y el achiote.', 'Agrega la lisa desmenuzada y la zanahoria, luego el arroz y revuelve bien.', 'Añade 4 tazas del caldo, cocina hasta que seque, tapa y deja a fuego bajo 20 minutos.']::text[], 'La lisa salada se conserva con sal desde los tiempos en que no había nevera. El arroz de lisa es emblema de Barranquilla y muy común en los pueblos del Bajo Magdalena.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('arepa-de-huevo', 'Arepa de huevo', 'fritos', 'Costa Atlántica (Luruaco, Atlántico)', 'Arepa de maíz frita, inflada y rellena con un huevo entero.', 45, 8, 'Media', array['2 tazas de harina de maíz amarillo precocida', '2 1/2 tazas de agua tibia', '1 cucharadita de sal', '1 cucharadita de azúcar', '8 huevos', 'Aceite para freír']::text[], array['Mezcla la harina, la sal, el azúcar y el agua hasta formar una masa suave que no se pegue.', 'Forma bolitas, aplánalas en discos delgados de unos 12 cm.', 'Fríe cada disco en aceite caliente hasta que se infle y forme un bolsillo.', 'Sácala, abre un pequeño corte en el borde y mete un huevo crudo.', 'Sella el corte con un poco de masa y vuelve a freír hasta que el huevo se cocine.']::text[], 'La arepa de huevo es el frito más famoso de la Costa. Luruaco, en el Atlántico, celebra cada año un festival dedicado a ella.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('carimanola', 'Carimañola', 'fritos', 'Caribe colombiano', 'Masa de yuca en forma de torpedo, rellena de carne o queso y frita.', 60, 10, 'Media', array['2 libras de yuca', '1/2 libra de carne molida guisada o queso costeño rallado', '1 cucharadita de sal', 'Aceite para freír']::text[], array['Cocina la yuca en agua con sal hasta que esté blanda. Escúrrela y retira la vena central.', 'Muele o machaca la yuca caliente hasta obtener una masa lisa.', 'Toma porciones de masa, ábrelas en la palma de la mano y pon el relleno en el centro.', 'Cierra dando forma alargada, como un torpedo.', 'Fríe en aceite bien caliente hasta que estén doradas por todos lados.']::text[], 'La carimañola es un desayuno típico de la Costa, muchas veces acompañada de suero o ají. Muestra la importancia de la yuca en la dieta del Caribe.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('bollo-limpio', 'Bollo limpio', 'fritos', 'Caribe colombiano', 'Masa de maíz blanco envuelta en hojas de mazorca y cocida.', 120, 10, 'Media', array['2 libras de maíz blanco seco', '1 cucharadita de sal', 'Hojas secas de mazorca (amero)', 'Pita o tiras de hoja para amarrar']::text[], array['Remoja el maíz desde la noche anterior y cocínalo hasta que ablande.', 'Muele el maíz dos veces hasta obtener una masa fina y agrégale la sal.', 'Pon porciones de masa sobre las hojas de mazorca, enróllalas y amarra los extremos.', 'Cocina los bollos en agua hirviendo durante 1 hora.', 'Sírvelos con queso costeño, suero o acompañando el mote de queso.']::text[], 'El bollo es el ''pan'' tradicional de la Costa. Su preparación, moliendo el maíz en molino de mano, era una labor familiar que reunía a varias generaciones.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('enyucado', 'Enyucado', 'dulces', 'Caribe colombiano', 'Torta horneada de yuca, coco, queso y anís.', 70, 8, 'Fácil', array['2 libras de yuca cruda rallada', '1 coco rallado', '1/2 libra de queso costeño rallado', '1 taza de azúcar', '1 cucharadita de anís en grano', '3 cucharadas de mantequilla derretida', '1/2 taza de leche']::text[], array['Precalienta el horno a 180 °C y engrasa un molde.', 'Mezcla la yuca, el coco, el queso, el azúcar y el anís.', 'Agrega la mantequilla y la leche hasta tener una mezcla húmeda y uniforme.', 'Vierte en el molde y hornea 50 a 60 minutos hasta que la superficie esté dorada.', 'Deja enfriar antes de cortar en cuadros.']::text[], 'El enyucado se vende en las tiendas y plazas de los pueblos costeños. Une tres productos de la tierra: yuca, coco y queso.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('cocadas', 'Cocadas', 'dulces', 'Caribe colombiano', 'Dulce de coco y panela cocido hasta caramelizar.', 40, 15, 'Fácil', array['2 cocos rallados', '1 panela rallada o 2 tazas de azúcar', '1 taza de agua', '1 astilla de canela', 'Jugo de 1/2 limón']::text[], array['Disuelve la panela en el agua con la canela a fuego medio.', 'Agrega el coco rallado y revuelve constantemente con cuchara de palo.', 'Añade el limón cuando la mezcla empiece a espesar.', 'Cocina hasta que se despegue del fondo del caldero.', 'Forma porciones con una cuchara sobre una tabla engrasada y deja enfriar.']::text[], 'Las cocadas son el dulce de las palenqueras y vendedoras ambulantes del Caribe. Son parte del paisaje de las plazas de Cartagena y de los pueblos de la región.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('jugo-de-corozo', 'Jugo de corozo', 'bebidas', 'Caribe colombiano', 'Refresco rojo y ácido de la fruta de la palma de corozo.', 30, 6, 'Fácil', array['2 tazas de corozo maduro', '6 tazas de agua', 'Azúcar al gusto', 'Hielo']::text[], array['Lava bien los corozos y cocínalos en 4 tazas de agua por 15 minutos.', 'Deja enfriar y machácalos para soltar la pulpa del hueso.', 'Licúa suavemente (sin romper la semilla) o macera con las manos.', 'Cuela, agrega el resto del agua y el azúcar.', 'Sirve bien frío con hielo.']::text[], 'El corozo es el fruto de una palma silvestre de la región. Su jugo rojo intenso es la bebida tradicional que acompaña los almuerzos costeños.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
insert into public.recetas (id, titulo, categoria, region, descripcion, tiempo_min, porciones, dificultad, ingredientes, pasos, contexto, informante) values ('chicha-de-maiz', 'Chicha de maíz', 'bebidas', 'Caribe colombiano', 'Bebida espesa de maíz cocido, endulzada y con especias.', 90, 8, 'Fácil', array['1 libra de maíz blanco peto', '10 tazas de agua', 'Panela o azúcar al gusto', 'Canela y clavos de olor', 'Leche (opcional)']::text[], array['Remoja el maíz durante la noche.', 'Cocínalo con canela y clavos hasta que esté muy blando.', 'Licúa el maíz con parte del agua de cocción.', 'Cuela, endulza con panela y, si deseas, agrega leche.', 'Sirve fría. Esta versión es sin fermentar, apta para toda la familia.']::text[], 'La chicha viene de tradiciones indígenas anteriores a la llegada de los españoles. En la Costa se prepara en fiestas patronales y reuniones familiares.', 'Receta de referencia — validar con la comunidad') on conflict (id) do nothing;
